changeSet.sql:
CREATE OR REPLACE TRIGGER trg_resolucion_dest_inmutable
BEFORE UPDATE OR DELETE ON resolucion_destinatario_log
BEGIN
    RAISE_APPLICATION_ERROR(-20005, 'El registro de resoluciones de destinatarios es inmutable');
END;

DECLARE
    v_admin       NUMBER;
    v_emp1        NUMBER;
    v_emp2        NUMBER;
    v_col_correo  NUMBER;
    v_cols        NUMBER;
    v_con_correo  NUMBER;
    v_sqlcode     NUMBER;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('TECNICO_MANTENIMIENTO', 'Tecnico de mantenimiento', 902);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);

    INSERT INTO usuario (full_name, corporate_email, role_code, status)
         VALUES ('Oraculo Directorio Admin', 'oraculo.tsk059.admin@example.invalid', 'ADMINISTRADOR', 'ACTIVO')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, role_code, status, created_by)
         VALUES ('Oraculo Directorio Empleado Uno', 'oraculo.tsk059.empleado1@example.invalid', 'EMPLEADO', 'ACTIVO', v_admin)
      RETURNING user_id INTO v_emp1;

    INSERT INTO usuario (full_name, corporate_email, role_code, status, created_by)
         VALUES ('Oraculo Directorio Empleado Dos', 'oraculo.tsk059.empleado2@example.invalid', 'EMPLEADO', 'ACTIVO', v_admin)
      RETURNING user_id INTO v_emp2;

    -- MITAD 1: el diccionario no conoce ninguna columna de correo en esta tabla.
    SELECT COUNT(*) INTO v_col_correo
      FROM user_tab_columns
     WHERE table_name = 'RESOLUCION_DESTINATARIO_LOG'
       AND (column_name LIKE '%EMAIL%' OR column_name LIKE '%MAIL%'
         OR column_name LIKE '%CORREO%' OR column_name LIKE '%ADDRESS%');
    IF v_col_correo <> 0 THEN
        RAISE_APPLICATION_ERROR(-20930, 'ORACULO REQ-081: la tabla declara ' || v_col_correo || ' columnas de correo; el registro solo admite identificadores');
    END IF;

    SELECT COUNT(*) INTO v_cols
      FROM user_tab_columns
     WHERE table_name = 'RESOLUCION_DESTINATARIO_LOG'
       AND column_name IN ('RESOLUTION_ID','REQUEST_TYPE','REQUESTED_BY_MODULE','SUBJECT_USER_ID','RESOLVED_USER_IDS','RECIPIENT_COUNT','IS_FALLBACK_USED','OUTCOME','RESOLVED_AT','RESOLVED_BY_USER_ID');
    IF v_cols <> 10 THEN
        RAISE_APPLICATION_ERROR(-20931, 'ORACULO REQ-081: el diccionario declara ' || v_cols || ' de las 10 columnas fisicas esperadas en RESOLUCION_DESTINATARIO_LOG');
    END IF;

    -- Tres filas representativas de los casos del requisito.
    -- a) Resolucion INDIVIDUAL: un unico destinatario, el propio empleado sujeto.
    INSERT INTO resolucion_destinatario_log (request_type, requested_by_module, subject_user_id, resolved_user_ids, recipient_count, is_fallback_used, outcome, resolved_by_user_id)
         VALUES ('INDIVIDUAL', 'MOD-002-AVISOS', v_emp1, '[' || v_emp1 || ']', 1, 'N', 'OK', v_admin);

    -- b) Resolucion COLECTIVO: sin sujeto, dos destinatarios resueltos.
    INSERT INTO resolucion_destinatario_log (request_type, requested_by_module, subject_user_id, resolved_user_ids, recipient_count, is_fallback_used, outcome, resolved_by_user_id)
         VALUES ('COLECTIVO', 'MOD-002-AVISOS', NULL, '[' || v_emp1 || ',' || v_emp2 || ']', 2, 'N', 'OK', v_admin);

    -- c) Resolucion COLECTIVO sin destinatarios: lista vacia y recuento cero.
    INSERT INTO resolucion_destinatario_log (request_type, requested_by_module, subject_user_id, resolved_user_ids, recipient_count, is_fallback_used, outcome, resolved_by_user_id)
         VALUES ('COLECTIVO', 'MOD-003-INCIDENCIAS', NULL, '[]', 0, 'N', 'SIN_DESTINATARIOS', v_admin);

    -- MITAD 2: ninguna fila del registro contiene un correo en claro.
    SELECT COUNT(*) INTO v_con_correo
      FROM resolucion_destinatario_log
     WHERE REGEXP_LIKE(resolved_user_ids, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}');
    IF v_con_correo <> 0 THEN
        RAISE_APPLICATION_ERROR(-20932, 'ORACULO AC-DIR-05: hay ' || v_con_correo || ' filas con un correo en claro en resolved_user_ids');
    END IF;

    -- MITAD 3: la base de datos rechaza activamente registrar un correo corporativo en claro.
    BEGIN
        INSERT INTO resolucion_destinatario_log (request_type, requested_by_module, subject_user_id, resolved_user_ids, recipient_count, is_fallback_used, outcome, resolved_by_user_id)
             VALUES ('COLECTIVO', 'MOD-002-AVISOS', NULL, '["empleado.uno@mapfre.com"]', 1, 'N', 'OK', v_admin);
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode = 0 THEN
        RAISE_APPLICATION_ERROR(-20933, 'ORACULO REQ-081: la base de datos ha aceptado registrar un correo corporativo en claro');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_admin    NUMBER;
    v_u1       NUMBER;
    v_u2       NUMBER;
    v_u3       NUMBER;
    v_res      NUMBER;
    v_count    NUMBER;
    v_card     NUMBER;
    v_sqlcode  NUMBER;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('TECNICO_MANTENIMIENTO', 'Tecnico de mantenimiento', 902);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);

    INSERT INTO usuario (full_name, corporate_email, role_code, status)
         VALUES ('Oraculo Cardinalidad Admin', 'oraculo.tsk059.card.admin@example.invalid', 'ADMINISTRADOR', 'ACTIVO')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, role_code, status, created_by)
         VALUES ('Oraculo Cardinalidad Uno', 'oraculo.tsk059.card1@example.invalid', 'EMPLEADO', 'ACTIVO', v_admin)
      RETURNING user_id INTO v_u1;

    INSERT INTO usuario (full_name, corporate_email, role_code, status, created_by)
         VALUES ('Oraculo Cardinalidad Dos', 'oraculo.tsk059.card2@example.invalid', 'EMPLEADO', 'ACTIVO', v_admin)
      RETURNING user_id INTO v_u2;

    INSERT INTO usuario (full_name, corporate_email, role_code, status, created_by)
         VALUES ('Oraculo Cardinalidad Tres', 'oraculo.tsk059.card3@example.invalid', 'EMPLEADO', 'ACTIVO', v_admin)
      RETURNING user_id INTO v_u3;

    -- Caso correcto: 3 identificadores resueltos y recuento 3.
    INSERT INTO resolucion_destinatario_log (request_type, requested_by_module, subject_user_id, resolved_user_ids, recipient_count, is_fallback_used, outcome, resolved_by_user_id)
         VALUES ('COLECTIVO', 'MOD-002-AVISOS', NULL, '[' || v_u1 || ',' || v_u2 || ',' || v_u3 || ']', 3, 'N', 'OK', v_admin)
      RETURNING resolution_id INTO v_res;

    SELECT recipient_count, resolved_ids_cardinalidad
      INTO v_count, v_card
      FROM resolucion_destinatario_log
     WHERE resolution_id = v_res;

    IF v_count <> 3 THEN
        RAISE_APPLICATION_ERROR(-20940, 'ORACULO REQ-081: recipient_count es ' || v_count || ' y se esperaban 3');
    END IF;

    IF v_card <> 3 THEN
        RAISE_APPLICATION_ERROR(-20941, 'ORACULO REQ-081: la cardinalidad real de resolved_user_ids es ' || v_card || ' y no coincide con los 3 destinatarios registrados');
    END IF;

    -- Sentido negativo: un recuento incoherente con la lista es rechazado por la base de datos.
    BEGIN
        INSERT INTO resolucion_destinatario_log (request_type, requested_by_module, subject_user_id, resolved_user_ids, recipient_count, is_fallback_used, outcome, resolved_by_user_id)
             VALUES ('COLECTIVO', 'MOD-002-AVISOS', NULL, '[' || v_u1 || ',' || v_u2 || ',' || v_u3 || ']', 2, 'N', 'OK', v_admin);
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode = 0 THEN
        RAISE_APPLICATION_ERROR(-20942, 'ORACULO REQ-081: la base de datos ha aceptado un recipient_count incoherente con la cardinalidad de resolved_user_ids');
    END IF;

    -- Regla hermana RN-04: SIN_DESTINATARIOS exige recuento cero.
    BEGIN
        INSERT INTO resolucion_destinatario_log (request_type, requested_by_module, subject_user_id, resolved_user_ids, recipient_count, is_fallback_used, outcome, resolved_by_user_id)
             VALUES ('COLECTIVO', 'MOD-002-AVISOS', NULL, '[' || v_u1 || ']', 1, 'N', 'SIN_DESTINATARIOS', v_admin);
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode = 0 THEN
        RAISE_APPLICATION_ERROR(-20943, 'ORACULO REQ-081 RN-04: SIN_DESTINATARIOS admitido con recipient_count distinto de 0');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;
